using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Aspire.Hosting.Testing;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;
    private static DistributedApplicationTestingBuilder? s_appHost;
    private static DistributedApplication? s_app;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        s_appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        s_app = await s_appHost.BuildAsync();
        await s_app.StartAsync();

        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (s_app is not null)
        {
            await s_app.StopAsync();
            await s_app.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var storagePath = Path.Combine(
            Path.GetDirectoryName(typeof(EvaluationTests).Assembly.Location)!,
            "evaluation-results");

        return DiskBasedReportingConfiguration.Create(
            storageRootPath: storagePath,
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfiguration: GetEvaluatorChatConfiguration());
    }

    private static ChatConfiguration GetEvaluatorChatConfiguration()
    {
        // The evaluator uses the same chat client from the app host.
        // In production, you may want a separate judge model.
        return new ChatConfiguration(
            chatClientFactory: serviceProvider =>
                serviceProvider.GetRequiredService<IChatClient>());
    }

    private IChatClient GetChatClient()
    {
        return s_app!.Services.GetRequiredService<IChatClient>();
    }

    [TestMethod]
    public async Task Chat_ReturnsRelevantResponse()
    {
        await using var scenarioRun = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_ReturnsRelevantResponse));

        var chatClient = GetChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenarioRun.EvaluateAsync(messages);

        Assert.IsTrue(
            response.Message.Text?.Contains("Paris", StringComparison.OrdinalIgnoreCase),
            "Expected the response to mention Paris.");
    }

    [TestMethod]
    public async Task Chat_HandlesFollowUpQuestions()
    {
        await using var scenarioRun = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_HandlesFollowUpQuestions));

        var chatClient = GetChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about .NET Aspire."),
        };

        var firstResponse = await chatClient.GetResponseAsync(messages);
        messages.Add(firstResponse.Message);

        messages.Add(new ChatMessage(ChatRole.User, "What are its main benefits?"));
        var secondResponse = await chatClient.GetResponseAsync(messages);
        messages.Add(secondResponse.Message);

        await scenarioRun.EvaluateAsync(messages);

        Assert.IsNotNull(secondResponse.Message.Text);
        Assert.IsTrue(secondResponse.Message.Text.Length > 0);
    }
}

